:root{--green:#0e5c33;--gold:#d4af37;--cream:#f7f2e6;--brown:#2e1f18;--rose:#b8735e}*{box-sizing:border-box}body{margin:0;background:#f5f5f2;color:#29231f;font-family:Arial,sans-serif}.sidebar{position:fixed;inset:0 auto 0 0;width:245px;background:var(--green);color:#fff;padding:28px 18px;display:flex;flex-direction:column;gap:7px}.brand{font:700 24px Georgia;margin:0 10px 28px}.brand small{font:11px Arial;letter-spacing:.2em;color:#d4af37}.sidebar a{color:#eef7f0;text-decoration:none;padding:12px 12px;border-radius:7px}.sidebar a:hover{background:rgba(255,255,255,.1)}.main{margin-left:245px;min-height:100vh}.top{height:66px;background:#fff;border-bottom:1px solid #ddd;display:flex;justify-content:space-between;align-items:center;padding:0 30px}.top a{color:var(--green);font-weight:700}.flash{margin:20px 30px;padding:13px 16px;border-radius:7px;background:#e9f6ed}.flash.error{background:#fde8e5}.content{padding:30px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,.panel{background:#fff;border:1px solid #e3e0db;border-radius:10px;padding:20px}.stat{font-size:28px;font-weight:800;margin-top:10px}.table{width:100%;border-collapse:collapse;background:#fff}.table th,.table td{padding:13px;border-bottom:1px solid #eee;text-align:left;font-size:14px}.btn{display:inline-block;border:0;background:var(--green);color:#fff;padding:10px 14px;border-radius:6px;text-decoration:none;cursor:pointer;font-weight:700}.btn.gold{background:var(--gold);color:#2e1f18}.btn.danger{background:#a63f35}.actions{display:flex;gap:8px;flex-wrap:wrap}.form{display:grid;gap:15px;max-width:850px}.form input,.form textarea,.form select{width:100%;padding:11px;border:1px solid #ccc;border-radius:6px;font:inherit}.form textarea{min-height:150px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}.preview{max-width:160px;border-radius:8px}.login{max-width:420px;margin:10vh auto;background:#fff;padding:35px;border-radius:12px}.login h1{font-family:Georgia}.muted{color:#777}@media(max-width:800px){.sidebar{position:static;width:auto;flex-direction:row;overflow:auto}.main{margin:0}.grid{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr}}@media(max-width:520px){.grid{grid-template-columns:1fr}.content{padding:15px}}
